/**
 * The public results page's numbers. summary.json is generated by scripts/build_benchmark_summary.py from the
 * committed reports and checked against them by tests/test_benchmark_summary.py: never edit numbers here.
 */
import data from './summary.json';

export type SystemId = 'deployed' | 'ngram' | 'routed2b' | 'copy' | 'sonnet';
export type SourceId = keyof typeof data.sources;

export interface LeaderRow {
  id: SystemId;
  n: number;
  top1: number;
  ci: [number, number] | null;
  matches: number;
  vs_deployed: { only_deployed: number; only_other: number; p: number; p_text: string } | null;
  source: string;
}

export interface Summary {
  github: string;
  sources: Record<SourceId, string>;
  leaderboard: Record<'full' | 'hard', { n: number; rows: LeaderRow[] }>;
  abstention: {
    n: number;
    coverage: number;
    selective_accuracy: number;
    filled: number;
    filled_matching: number;
    ece: number;
    reliability: { lo: number; hi: number; n: number; accuracy: number | null; confidence: number | null }[];
    source: string;
  };
  gap_length: { bins: ({ key: string; n: number } & Record<'deployed' | 'ngram' | 'routed2b' | 'copy', number>)[]; source: string };
  ocr: {
    tamil_synthetic: Record<'clean' | 'photo' | 'weathered', { n: number; cer: number }>;
    printed_pages: { n: number; cer: number };
    brahmi_real: { n: number; cer: number };
    source: string;
  };
  decider: {
    hosted: { n: number; hosted_matching: number; chosen_matching: number; only_hosted: number; only_chosen: number; p_text: string; over_limit: number; limit_s: number; source: string };
    sparrow: { n: number; best_top1: number; random_top3: number; first_candidate: number; nano_policy_raw: number; nano_policy_final: number; policy_n: number; source: string };
  };
  method: {
    splits: Record<'train' | 'val' | 'test', { inscriptions: number; items: number }>;
    test_hard: number;
    val_selection_n: number;
    bootstrap_resamples: number;
  };
}

export const SUMMARY = data as unknown as Summary;

/** GitHub link for a repository path cited as a source. */
export function sourceUrl(path: string): string {
  return `${SUMMARY.github}${path}`;
}
